+      margin: 0 0 28px;
+      color: var(--muted);
+      line-height: 1.5;
+    }
+
+    form {
+      display: grid;
+      gap: 18px;
+    }
+
+    .form-field {
+      display: grid;
+      gap: 8px;
+    }
+
+    label {
+      font-weight: 600;
+    }
+
+    input {
+      width: 100%;
+      border: 1px solid var(--line);
+      border-radius: 14px;
+      padding: 14px 16px;
+      font: inherit;
+      background: #fff;
+      color: var(--text);
+      transition: border-color 0.15s ease, box-shadow 0.15s ease;
+    }
+
+    input::placeholder {
+      color: #95a0b4;
+    }
+
+    input:focus {
+      outline: none;
+      border-color: var(--focus);
+      box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.12);
+    }
+
+    .helper-text,
+    .error-message {
+      font-size: 0.92rem;
+      line-height: 1.4;
+    }
+
+    .helper-text {
+      color: var(--muted);
+    }
+
+    .error-message {
+      color: var(--error);
+      min-height: 1.3em;
+    }
+
+    .form-field.has-error input {
+      border-color: var(--error);
+      box-shadow: 0 0 0 4px rgba(198, 40, 40, 0.08);
+    }
+
+    button {
+      appearance: none;
+      border: 0;
+      border-radius: 14px;
+      padding: 14px 18px;
+      background: linear-gradient(135deg, #2563eb, #1d4ed8);
+      color: #fff;
+      font: inherit;
+      font-weight: 700;
+      cursor: pointer;
+      box-shadow: 0 10px 24px rgba(37, 99, 235, 0.25);
+      transition: transform 0.15s ease, box-shadow 0.15s ease;
+    }
+
+    button:hover {
+      transform: translateY(-1px);
+      box-shadow: 0 14px 28px rgba(37, 99, 235, 0.28);
+    }
+
+    button:focus-visible {
+      outline: 3px solid rgba(37, 99, 235, 0.35);
+      outline-offset: 2px;
+    }
+
+    .form-status {
+      margin: 6px 0 0;
+      min-height: 1.4em;
+      color: var(--muted);
+    }
+  </style>
+</head>
+<body>
+  <main>
+    <section class="card" aria-labelledby="support-title">
+      <h1 id="support-title">Contact support</h1>
+      <p class="subtitle">Send us your details and we’ll get back to you as soon as possible.</p>
+
+      <form id="support-form" novalidate>
+        <div class="form-field" id="name-field">
+          <label for="full-name">Full name</label>
+          <input id="full-name" name="fullName" type="text" autocomplete="name" required placeholder="Jane Doe" aria-describedby="full-name-error" />
+          <div class="error-message" id="full-name-error" aria-live="polite"></div>
+        </div>
+
+        <div class="form-field" id="email-field">
+          <label for="email-address">Email address</label>
+          <input id="email-address" name="emailAddress" type="email" autocomplete="email" required placeholder="jane@example.com" aria-describedby="email-address-error" />
+          <div class="error-message" id="email-address-error" aria-live="polite"></div>
+        </div>
+
+        <div class="form-field" id="phone-field">
+          <label for="phone-number">Phone number</label>
+          <input id="phone-number" name="phoneNumber" type="tel" autocomplete="tel" inputmode="tel" placeholder="(555) 123-4567" aria-describedby="phone-number-help phone-number-error" />
+          <div class="helper-text" id="phone-number-help">Optional. Use a phone number in the format +1 555 123 4567 or (555) 123-4567.</div>
+          <div class="error-message" id="phone-number-error" aria-live="polite"></div>
+        </div>
+
+        <button type="submit">Submit</button>
+        <p class="form-status" id="form-status" aria-live="polite"></p>
+      </form>
+    </section>
+  </main>
+
+  <script>
+    const form = document.getElementById('support-form');
+    const statusMessage = document.getElementById('form-status');
+
+    const fields = {
+      fullName: {
+        input: document.getElementById('full-name'),
+        field: document.getElementById('name-field'),
+        error: document.getElementById('full-name-error'),
+        validate(value) {
+          if (!value.trim()) return 'Full name is required.';
+          return '';
+        },
+      },
+      emailAddress: {
+        input: document.getElementById('email-address'),
+        field: document.getElementById('email-field'),
+        error: document.getElementById('email-address-error'),
+        validate(value) {
+          if (!value.trim()) return 'Email address is required.';
+          if (!fields.emailAddress.input.validity.valid) return 'Enter a valid email address.';
+          return '';
+        },
+      },
+      phoneNumber: {
+        input: document.getElementById('phone-number'),
+        field: document.getElementById('phone-field'),
+        error: document.getElementById('phone-number-error'),
+        validate(value) {
+          const trimmed = value.trim();
+          if (!trimmed) return '';
+          const phonePattern = /^(?:\+?\d{1,3}[\s.-]?)?(?:\(?\d{3}\)?[\s.-]?)\d{3}[\s.-]?\d{4}$/;
+          if (!phonePattern.test(trimmed)) {
+            return 'Enter a valid phone number, such as +1 555 123 4567.';
+          }
+          return '';
+        },
+      },
+    };
+
+    function setFieldState(name, message) {
+      const { field, input, error } = fields[name];
+      const hasError = Boolean(message);
+
+      field.classList.toggle('has-error', hasError);
+      input.setAttribute('aria-invalid', String(hasError));
+      error.textContent = message;
+    }
+
+    function validateField(name) {
+      const { input, validate } = fields[name];
+      const message = validate(input.value);
+      setFieldState(name, message);
+      return !message;
+    }
+
+    Object.keys(fields).forEach((name) => {
+      fields[name].input.addEventListener('blur', () => validateField(name));
+      fields[name].input.addEventListener('input', () => {
+        if (fields[name].field.classList.contains('has-error')) {
+          validateField(name);
+        }
+        statusMessage.textContent = '';
+      });
+    });
+
+    form.addEventListener('submit', (event) => {
+      event.preventDefault();
+
+      const isValid = Object.keys(fields).map(validateField).every(Boolean);
+
+      if (!isValid) {
+        statusMessage.textContent = 'Please fix the highlighted fields and try again.';
+        return;
+      }
+
+      statusMessage.textContent = 'Thanks — your message is ready to send.';
+      form.reset();
+      Object.keys(fields).forEach((name) => setFieldState(name, ''));
+    });
+  </script>
+</body>
+</html>
*** End Patch
