     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       background:
         radial-gradient(circle at top, rgba(37, 99, 235, 0.09), transparent 35%),
         var(--bg);
